#!/usr/bin/env bash
# Round 492 claims (B-R488-PASSWORD-MODAL-DIALOG). Usage: bash claims-492.sh   (ROOT=<store tree> LOOP=<loop folder> BASE=<base rev> may be overridden)
# Planning output on the clean store tree (HEAD e4e1d1c): claims-492-planning-output.txt.
# Sketch output on B's scratch (/tmp/b492-scratch = e4e1d1c content + sketch v3; ROOT=/tmp/b492-scratch BASE=HEAD): claims-492-sketch-output.txt.
ROOT=${ROOT:-/home/runner/czaba-project/store}
LOOP=${LOOP:-/home/runner/czaba-project/tmp/studio-real-loop}
BASE=${BASE:-e4e1d1c}
B=$LOOP/b-round-491
A=app/routes/account.tsx
D15=docs/implementation/2026/quarter-IV/315-profile-name-keyboard.md
D17=docs/implementation/2026/quarter-IV/317-profile-editor-narrow-overflow.md
D18=docs/implementation/2026/quarter-IV/318-password-dialog-semantics.md
T1=app/lib/__tests__/account-password-dialog.test.tsx
T2=app/lib/__tests__/account-profile-name.test.tsx
cd "$ROOT" || exit 1
echo "K1 gate491 $(python3 -I -c "import json;d=json.load(open('$LOOP/gates/gate-round-491.json'));print(d['status'],d['commit'][:7])")"
echo "K2 paths=$(git status --porcelain --untracked-files=all | awk '{print $1":"$2}' | sort | tr '\n' ' ')"
echo "K3 root-tsx-diff $(git diff --numstat $BASE -- app/root.tsx app/styles | wc -l) protected-diff $(git diff --numstat $BASE -- 'app/routes/studio.$productId.tsx' app/routes/api.studio-token.ts app/routes/account.downloads.tsx app/contexts/AuthContext.tsx app/lib/auth.ts app/components/ui/Modal.tsx | wc -l) other-app-diff $(git diff --name-only $BASE -- app | grep -vE "^($A|$T2)$" | wc -l)"
echo "K4 account dialog=$(grep -c 'role="dialog"' $A) aria-modal=$(grep -c 'aria-modal="true"' $A) labelledby=$(grep -c 'aria-labelledby={titleId}' $A) htmlFor=$(grep -c '<label htmlFor=' $A) bare-label=$(grep -c '<label className="block text-sm text-muted mb-2">' $A) eye-labels=$(grep -cE "aria-label=\{?\s*show(Current|New|Confirm)Password \?" $A) alert=$(grep -c 'role="alert"' $A) trigger-type=$(grep -c 'ref={passwordTriggerRef}' $A) isPresent=$(grep -c 'useIsPresent()' $A) inert=$(grep -c 'dialogRef.current.inert = !isPresent;' $A) composing=$(grep -c 'e.isComposing' $A) close-guard=$(grep -c 'if (!passwordModalOpenRef.current) {' $A) modal-ref=$(grep -c 'passwordModalOpenRef' $A) backdrop-testid=$(grep -c 'data-testid="password-dialog-backdrop"' $A)"
echo "K5 sketch-492-files $(cd "$B/sketch-492" && for f in $(find . -type f | sort); do cmp -s "$f" "$ROOT/$f" && echo -n "=" || echo -n "x"; done) patch=$(sha256sum "$B/sketch-492.patch.txt" | cut -c1-16) recorded=$(cut -c1-16 "$B/sketch-492.sha256")"
echo "K6 SWEEP app/perf/e2e tests: backdrop-testid=$(grep -rl 'password-dialog-backdrop' app perf e2e --include='*.test.*' --include='*.spec.*' 2>/dev/null | sort | tr '\n' ' ') pw-names=$(grep -rlE "Click to change password|Change Password|Current Password|Update Password" app perf e2e --include='*.test.*' --include='*.spec.*' 2>/dev/null | sort | tr '\n' ' ') account-readers=$(grep -rlE "account\.tsx|routes/account['\"]" app perf e2e --include='*.test.*' --include='*.spec.*' 2>/dev/null | sort | tr '\n' ' ')"
echo "K7 covering $(sed 's/\x1b\[[0-9;]*m//g' "$B/sketch-492-covering.log" | grep -E '^\s+(Test Files|Tests) ' | tr -s ' ' | tr '\n' ' ') $(grep -o 'rc=[0-9]*' "$B/sketch-492-covering.log")"
echo "K8 full-suite $(sed 's/\x1b\[[0-9;]*m//g' "$B/precheck-full-492.log" | grep -E '^\s+(Test Files|Tests) ' | tr -s ' ' | tr '\n' ' ') $(grep -o '^rc [0-9]*' "$B/precheck-full-492.log")"
echo "K9 typecheck-sketch $(grep -c 'error TS' "$B/sketch-492-typecheck.log") $(tail -1 "$B/sketch-492-typecheck.log") biome-live $(npx biome check $A 2>&1 | grep -oE 'Found [0-9]+ (warning|error)s?' | tr '\n' ' ')"
echo "K10 docs d318-l4=$(sed -n 4p $D18 2>/dev/null) d318-headings=$(grep -c '^## ' $D18 2>/dev/null) d315-b-r488-todo-old=$(grep -c 'TODO: B-R488-PASSWORD-MODAL-DIALOG' $D15) d315-fixed=$(grep -c 'B-R488-PASSWORD-MODAL-DIALOG (Medium) — გამოსწორდა round 492-ში (doc 318)' $D15) d315-pn10fg=$(grep -c 'dialog focus-ს Current Password-ზე გადაიტანს (round 492, doc 318)' $D15) d317-old=$(grep -c 'დაგეგმილია შემდეგ რაუნდში' $D17) d317-fixed=$(grep -c 'გამოსწორდა round 492-ში (doc 318)' $D17) pending-form=$(grep -rl 'C round [0-9]* pending' docs/implementation | wc -l)"
echo "K11 probe-head $(tail -1 "$B/probe/pw-check-head.txt" | tr '\n' ' ')$(grep -cE '^[0-9]+x[0-9]+ [A-Z0-9-]+ RED' "$B/probe/pw-check-head.txt") red-rows $(grep -cE '^[0-9]+x[0-9]+ [A-Z0-9-]+ PASS' "$B/probe/pw-check-head.txt") pass-rows"
echo "K12 probe-sketch $(grep -c ' PASS ' "$B/probe/pw-check-sketch.txt") pass-rows $(grep 'PW-CHECK' "$B/probe/pw-check-sketch.txt") mutO $(grep 'PW-CHECK' "$B/probe/pw-check-mutO.txt") mutO-red=$(grep ' RED ' "$B/probe/pw-check-mutO.txt" | awk '{print $2}' | sort -u | tr '\n' ' ') open-pxdiff=$(grep -c '"n":0,' "$B/probe/open-pxdiff.txt")/3"
echo "K13 mutants $(grep -c ' RED ' "$B/mutants/mutants-summary.txt") RED $(grep -c 'SURVIVED\|NOT-APPLIED' "$B/mutants/mutants-summary.txt") other; $(head -1 "$B/mutants/mutants-summary.txt")"
echo "K14 l58 $(cd "$LOOP" && python3 -I tools/l58-check.py current-task.md 2>&1 | tail -1)"
echo "K15 cited $(for f in b-round-491/sketch-492.patch.txt b-round-491/sketch-492.sha256 b-round-491/sketch-492-v1.patch.txt b-round-491/sketch-492-v2.patch.txt b-round-491/sketch-492-v1-to-v2.diff.txt b-round-491/sketch-492-v2-to-v3.diff.txt b-round-491/sketch-review.md b-round-491/sketch-492-covering.log b-round-491/precheck-full-492.log b-round-491/sketch-492-typecheck.log b-round-491/sketch-492-biome.log b-round-491/probe/pw-492.mjs b-round-491/probe/pw-check.py b-round-491/probe/serve-prod.sh b-round-491/probe/headprod-pw.json b-round-491/probe/sketchprod-pw.json b-round-491/probe/mutO-pw.json b-round-491/probe/pw-check-head.txt b-round-491/probe/pw-check-sketch.txt b-round-491/probe/pw-check-mutO.txt b-round-491/probe/open-pxdiff.txt b-round-491/probe/open-pxdiff.mjs b-round-491/probe/shots/headprod-open-1440x900.png b-round-491/probe/shots/sketchprod-open-1440x900.png b-round-491/probe/shots/sketchprod-open-375x812.png b-round-491/probe/shots/sketchprod-error-1280x720.png b-round-491/mutants/run-mutants.py b-round-491/mutants/mutants-summary.txt tasks/round-491.md b-round-491/current-task-before-492.md b-round-491/claims-492-planning-output.txt b-round-491/claims-492-sketch-output.txt b-round-491/checkpoint-request-account-492.md; do test -f "$LOOP/$f" && echo -n 1 || echo -n "0($f)"; done)"
echo "K16 ids $(python3 -I "$LOOP/tools/find-ids.py" "$LOOP" B-R488-PASSWORD-MODAL-DIALOG B-R492-PASSWORD-FIELDS-UNNAMED B-R492-PASSWORD-ERROR-NOT-ANNOUNCED B-R492-PASSWORD-CHANGE-NOT-IMPLEMENTED A-R488-REVIEW-L1-EXIT-ANIMATION-WINDOW shared-modal-no-focus-management B-R487-PROFILE-EDITOR-NARROW-OVERFLOW | awk '{print $1":"($2=="NOT-FOUND"?"NOT-FOUND":"found")}' | tr '\n' ' ') tlm=$(python3 -I -c "import json;b=json.load(open('$LOOP/backlog.json'));print(sum(1 for r in b['tech_lead_manual_checks'] if r.get('id')=='TLM-R492-SR-PASSWORD-DIALOG'))")"
echo "K17 lessons lines=$(wc -l < "$LOOP/lessons.md")"
echo "K18 L50 focus-origin hits account.tsx=$(grep -cE 'onPointerDown(Capture)?|onBlur|settleEditor\(|\.focus\(|^\s*\{[^}]*(\.map\(|&&|\?)' $A) lines=$(grep -nE 'onPointerDown(Capture)?|onBlur|settleEditor\(|\.focus\(|^\s*\{[^}]*(\.map\(|&&|\?)' $A | cut -d: -f1 | tr '\n' ',')"
echo "K19 auth.ts updatePassword-throws=$(grep -c "Password change is not yet implemented. Please use the forgot password feature." app/lib/auth.ts) focus-source-rule=$(grep -c 'html\[data-focus-source="pointer"\] :focus-visible' app/styles/app.css)"
echo "K20 shared-modal bg95=$(grep -c 'bg-black/95' app/components/ui/Modal.tsx) z1000=$(grep -c 'z-\[1000\]' app/components/ui/Modal.tsx) portal=$(grep -c 'createPortal(modalContent, document.body)' app/components/ui/Modal.tsx) focus-calls=$(grep -c '\.focus(' app/components/ui/Modal.tsx)"
